func TestDetect_leadingCommentDoesNotHideTheWrapper(t *testing.T) {
	docComment := `/* === tool-doc ===\nfunction: tool-css-unit-converter\n... */`
	for name, script := range map[string]string{
		"block comment": docComment + "\n(function () {\n  var x = 1;\n})();",
		"line comments": "// tool-doc\n// second line\n(function () { var x = 1; })();",
		"both":          "// lead\n" + docComment + "\n(function () { var x = 1; })();",
	} {
		if got := DetectInstanceCollisions(`<script>`+script+`</script>`); got.UnscopedInlineScripts != 0 {
			t.Fatalf("%s: an IIFE behind a leading comment must read as scoped", name)
		}
	}
	// CONTROL: the same comment must not launder a global declaration
	if DetectInstanceCollisions(`<script>`+docComment+"\nfunction runCalc() {}\n</script>").UnscopedInlineScripts != 1 {
		t.Fatal("CONTROL FAILED")
	}
	// and an INNER comment changes nothing
	if DetectInstanceCollisions(`<script>function f() { /* note */ }</script>`).UnscopedInlineScripts != 1 {
		t.Fatal("inner comment must not affect the verdict")
	}
}
